// @generated by:gauntlet run:hypothesis-exports
mod common;

use anatoly::{
    scan::{Report, scan_configured},
    scan_options::ScanOptions,
};
use common::{Server, limits, response};
use serde_json::{Value, json};
use std::{
    fs,
    path::PathBuf,
    process::{Command, Output},
    sync::atomic::{AtomicU64, Ordering},
};

static NEXT_FILE: AtomicU64 = AtomicU64::new(0);

#[derive(Default)]
struct Files(Vec<PathBuf>);

impl Files {
    fn path(&mut self, extension: &str) -> PathBuf {
        let unique = NEXT_FILE.fetch_add(1, Ordering::Relaxed);
        let path = std::env::temp_dir().join(format!(
            "anatoly-hypothesis-{}-{unique}.{extension}",
            std::process::id()
        ));
        assert!(!path.exists());
        self.0.push(path.clone());
        path
    }
    fn json(&mut self, value: &Value) -> PathBuf {
        let path = self.path("json");
        let file = fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&path)
            .unwrap();
        serde_json::to_writer(file, value).unwrap();
        path
    }
}

impl Drop for Files {
    fn drop(&mut self) {
        for path in &self.0 {
            if path.exists() {
                fs::remove_file(path).unwrap();
            }
        }
    }
}

fn options() -> ScanOptions {
    let mut options = ScanOptions {
        samples: 1,
        discover: false,
        ..ScanOptions::default()
    };
    options.network.no_proxy = true;
    options
}

fn cli(args: &[&str]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_anatoly"))
        .args(args)
        .output()
        .unwrap()
}

fn snapshot() -> Value {
    let server = Server::new(|_| {
        response(
            "200 OK",
            "Set-Cookie: laravel-session=PRIVATE_FIXTURE; Path=/\r\n",
            "application",
        )
    });
    let target = scan_configured(&server.url, limits(), &options()).unwrap();
    serde_json::to_value(Report::new(vec![target])).unwrap()
}

fn parsed(output: &Output) -> Value {
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    serde_json::from_slice(&output.stdout).unwrap()
}

#[test]
fn framework_php_requirements_cite_only_matching_version_observations() {
    let server = Server::new(|path| match path {
        "/legacy" => response("200 OK", "X-Powered-By: Laravel/12.70.2\r\n", "application"),
        "/modern" => response("200 OK", "X-Powered-By: Laravel/13.0.0\r\n", "application"),
        _ => response(
            "200 OK",
            "Set-Cookie: laravel-session=PRIVATE_FIXTURE\r\n",
            "application",
        ),
    });
    let mut settings = options();
    settings.discover = true;
    settings.paths = vec!["legacy".into(), "modern".into(), "unversioned".into()];
    let mut bounds = limits();
    bounds.max_requests = 8;
    let target =
        serde_json::to_value(scan_configured(&server.url, bounds, &settings).unwrap()).unwrap();
    assert_eq!(server.paths.lock().unwrap().len(), 4);
    let hypotheses = target["version_hypotheses"].as_array().unwrap();
    for (range, expected, forbidden) in [
        (">=8.2", "/legacy", "/modern"),
        (">=8.3", "/modern", "/legacy"),
    ] {
        let requirement = hypotheses
            .iter()
            .find(|h| {
                h["technology"] == "PHP"
                    && h["range"] == range
                    && h["basis"] == "framework_requirement"
            })
            .unwrap();
        let sources = requirement["sources"].as_array().unwrap();
        assert!(!sources.is_empty());
        assert!(
            sources
                .iter()
                .all(|source| source.as_str().unwrap().contains(expected)),
            "{requirement}"
        );
        assert!(
            !sources
                .iter()
                .any(|source| source.as_str().unwrap().contains(forbidden))
        );
        assert!(
            !sources
                .iter()
                .any(|source| source.as_str().unwrap().contains("/unversioned"))
        );
    }
    assert_eq!(target["version_status"], "unknown");
    assert!(target["version"].is_null());
}

#[test]
fn composer_hyphen_single_pipe_and_spaced_comparators_preserve_original_constraints() {
    for constraint in ["8.1 - 8.3", "^8.1 | ^8.2", ">= 8.2 < 9"] {
        let body = json!({"require":{"php":constraint}}).to_string();
        let server = Server::new(move |_| response("200 OK", "", &body));
        let report = serde_json::to_value(
            scan_configured(
                &format!("{}composer.json", server.url),
                limits(),
                &options(),
            )
            .unwrap(),
        )
        .unwrap();
        let candidate = report["version_hypotheses"]
            .as_array()
            .unwrap()
            .iter()
            .find(|h| h["technology"] == "PHP" && h["range"] == constraint)
            .unwrap_or_else(|| panic!("missing constraint {constraint}: {report}"));
        assert_eq!(candidate["confidence"], "low");
        assert!(report["version"].is_null());
        assert_eq!(report["version_candidates"], json!([]));
        assert_eq!(report["verdict"], "inconclusive");
    }
}

#[test]
fn terminal_displays_version_hypotheses_as_unverified_ranges() {
    let server = Server::new(|_| {
        response(
            "200 OK",
            "Set-Cookie: laravel-session=PRIVATE_FIXTURE\r\n",
            "application",
        )
    });
    let output = cli(&[
        "scan",
        &server.url,
        "--samples",
        "1",
        "--no-discover",
        "--delay-ms",
        "0",
        "--no-proxy",
        "--no-banner",
        "--color",
        "never",
        "--fail-on",
        "never",
    ]);
    assert!(output.status.success());
    let terminal = String::from_utf8(output.stdout).unwrap();
    assert!(terminal.contains("VERSION HYPOTHESES"));
    assert!(terminal.contains("Laravel"));
    assert!(terminal.contains(">=12"));
    assert!(terminal.contains("never patch evidence"));
    assert!(!terminal.contains("PRIVATE_FIXTURE"));
}

#[test]
fn saved_json_explanations_preserve_the_structured_hypothesis_collection() {
    let report = snapshot();
    assert!(
        !report["targets"][0]["version_hypotheses"]
            .as_array()
            .unwrap()
            .is_empty()
    );
    let mut files = Files::default();
    let input = files.json(&report);
    let output = cli(&["explain", input.to_str().unwrap(), "--json"]);
    let explained = parsed(&output);
    assert_eq!(
        explained["targets"][0]["version_hypotheses"],
        report["targets"][0]["version_hypotheses"]
    );
    assert!(explained["targets"][0]["version"].is_null());
}

#[test]
fn html_reports_label_hypotheses_and_escape_their_untrusted_text() {
    let mut report = snapshot();
    report["targets"][0]["version_hypotheses"][0]["range"] = json!(">=8.2,<9");
    report["targets"][0]["version_hypotheses"][0]["reasons"] =
        json!(["<script>PRIVATE_SCRIPT_FIXTURE</script>"]);
    let mut files = Files::default();
    let input = files.json(&report);
    let output = files.path("html");
    let result = cli(&[
        "report",
        input.to_str().unwrap(),
        "--output",
        output.to_str().unwrap(),
        "--json",
    ]);
    assert!(
        result.status.success(),
        "{}",
        String::from_utf8_lossy(&result.stderr)
    );
    let html = fs::read_to_string(output).unwrap();
    assert!(html.contains("Unverified version hypotheses"));
    assert!(html.contains("&lt;9"));
    assert!(!html.contains("<script>"));
    assert!(html.contains("&lt;script&gt;PRIVATE_SCRIPT_FIXTURE&lt;/script&gt;"));
}

#[test]
fn comparisons_detect_changes_confined_to_version_hypotheses() {
    let baseline = snapshot();
    let mut current = baseline.clone();
    current["targets"][0]["version_hypotheses"][0]["range"] = json!(">=13");
    let mut files = Files::default();
    let before = files.json(&baseline);
    let after = files.json(&current);
    let output = cli(&[
        "compare",
        before.to_str().unwrap(),
        after.to_str().unwrap(),
        "--json",
    ]);
    assert_eq!(output.status.code(), Some(1));
    let comparison: Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(comparison["changed"], true);
    assert_eq!(comparison["changes"].as_array().unwrap().len(), 1);
    assert_eq!(
        comparison["changes"][0]["current"]["version_hypotheses"],
        current["targets"][0]["version_hypotheses"]
    );
    assert_eq!(
        comparison["changes"][0]["baseline"]["version_hypotheses"],
        baseline["targets"][0]["version_hypotheses"]
    );
}

#[test]
fn version_requirement_policy_cannot_pass_from_hypotheses_alone() {
    let report = snapshot();
    let mut files = Files::default();
    let input = files.json(&report);
    let rules = files.json(&json!({"require_https":false,"no_affected":false,"no_diagnostics":false,"require_version":true}));
    let output = cli(&[
        "policy",
        input.to_str().unwrap(),
        "--rules",
        rules.to_str().unwrap(),
        "--json",
    ]);
    assert_eq!(output.status.code(), Some(1));
    let policy: Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(policy["status"], "fail");
    assert_eq!(policy["targets"][0]["checks"][0]["rule"], "require_version");
    assert_eq!(policy["targets"][0]["checks"][0]["status"], "fail");
}

#[test]
fn older_reports_without_structured_hypotheses_remain_accepted() {
    let mut report = snapshot();
    report["targets"][0]
        .as_object_mut()
        .unwrap()
        .remove("version_hypotheses");
    let mut files = Files::default();
    let input = files.json(&report);
    let output = cli(&["explain", input.to_str().unwrap(), "--json"]);
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    let explanation: Value = serde_json::from_slice(&output.stdout).unwrap();
    assert!(explanation["targets"][0]["version"].is_null());
}

#[test]
fn resolved_two_component_lock_tags_are_not_expanded_into_patch_hypotheses() {
    for (path, body, name) in [
        (
            "composer.lock",
            json!({"packages":[{"name":"psr/http-message","version":"2.0"}]}),
            "composer:psr/http-message",
        ),
        (
            "package-lock.json",
            json!({"lockfileVersion":2,"packages":{"node_modules/custom-compat-library":{"version":"2.0"}}}),
            "npm:custom-compat-library",
        ),
    ] {
        let body = body.to_string();
        let server = Server::new(move |_| response("200 OK", "", &body));
        let report = serde_json::to_value(
            scan_configured(&format!("{}{path}", server.url), limits(), &options()).unwrap(),
        )
        .unwrap();
        let package = report["technologies"]
            .as_array()
            .unwrap()
            .iter()
            .find(|technology| technology["name"] == name)
            .unwrap();
        assert_eq!(package["versions"], json!(["2.0"]));
        assert!(
            !report["version_hypotheses"]
                .as_array()
                .unwrap()
                .iter()
                .any(|hypothesis| hypothesis["technology"] == name)
        );
        assert!(report["version"].is_null());
    }
    let server =
        Server::new(|_| response("200 OK", "X-Powered-By: WordPress/6.8\r\n", "application"));
    let report =
        serde_json::to_value(scan_configured(&server.url, limits(), &options()).unwrap()).unwrap();
    assert!(report["version_hypotheses"].as_array().unwrap().iter().any(
        |hypothesis| hypothesis["technology"] == "WordPress" && hypothesis["range"] == "6.8.x"
    ));
}
